{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.cablate/google-map",
  "title": "Google Maps MCP Server",
  "description": "18 Google Maps tools for AI agents — geocode, search, directions, weather, and more.",
  "repository": {
    "url": "https://github.com/cablate/mcp-google-map",
    "source": "github"
  },
  "version": "0.0.53",
  "packages": [
    {
      "registryType": "npm",
      "identifier": "@cablate/mcp-google-map",
      "version": "0.0.53",
      "transport": {
        "type": "stdio"
      },
      "environmentVariables": [
        {
          "name": "GOOGLE_MAPS_API_KEY",
          "description": "Google Maps API key (get one at https://console.cloud.google.com)",
          "isRequired": true,
          "format": "string",
          "isSecret": true
        },
        {
          "name": "GOOGLE_MAPS_ENABLED_TOOLS",
          "description": "Comma-separated tool names to enable. Omit or * for all 18 tools.",
          "isRequired": false,
          "format": "string",
          "isSecret": false
        }
      ]
    }
  ]
}
